  final String? paperNumber;
  final String? subject;
  final String? subjectEng;
  final String? setNumber;
  final int? fullMarks;
  final int? passMarks;
  final String? timeDuration;

  const ModelPaper({
    required this.tabLabel,
    this.commissionName = 'लोक सेवा आयोग',
    required this.serviceName,
    this.examType = 'खुल्ला तथा समावेशी प्रतियोगितात्मक लिखित परीक्षा — Model Question Paper',
    this.examDate = '२०८१',
    required this.timeString,
    required this.fullMarksString,
    required this.paperTitle,
    required this.subjectTitle,
    required this.instructionsText,
    required this.icon,
    required this.sections,
    this.paperNumber,
    this.subject,
    this.subjectEng,
    this.setNumber,
    this.fullMarks,
    this.passMarks,
    this.timeDuration,
  });
}

class ModelSection {
  final String title;
  final String? subtitle;
  final int totalMarks;
  final List<ModelQuestion> questions;

  const ModelSection({
    required this.title,
    this.subtitle,
    required this.totalMarks,
    required this.questions,
  });
}

class ModelQuestion {
  final int number;
  final String? subLabel;
  final String questionText;
  final String? questionTextNepali;
  final List<String>? options;
  final int? marks;
  final String marksBreakdown;
  final String answer;
  final bool isPremium;

  const ModelQuestion({
    required this.number,
    this.subLabel,
    required this.questionText,
    this.questionTextNepali,
    this.options,
    this.marks,
    required this.marksBreakdown,
    required this.answer,
    this.isPremium = false,
  });
}

